# Generated by scripts/installer/build.mjs from scripts/installer/ps1/; edit the parts, then run bun scripts/installer/build.mjs.
# Get-Help skips a help block that touches the comment above it (the bundle notice), so keep the blank line below.

<#
.SYNOPSIS
Installs, checks, updates, or removes the snipset CLI on Windows.

.DESCRIPTION
Downloads the snipset-cli release zip for x86_64-pc-windows-msvc, verifies it against SHA256SUMS,
and places snipset.exe in the install directory. Every step prints one report line. Usage errors,
refusals, and drift throw, so "pwsh -File install.ps1" ends with status 1. The script never closes the
session it runs in, because the documented one-liner runs it as a scriptblock inside your own session.

.PARAMETER Version
Release to install, for example v0.1.0 or 0.1.0. Defaults to the latest GitHub release.

.PARAMETER InstallDir
Directory for snipset.exe. Defaults to $env:LOCALAPPDATA\Snipset\bin.

.PARAMETER AddPath
Also add the install directory to the user PATH.

.PARAMETER WithMcp
Register the snipset MCP server with these harnesses: claude, codex, gemini, opencode, cursor, vscode,
or all. Accepts one comma-separated string or several strings.

.PARAMETER From
Install from a local directory holding SHA256SUMS and the release zip instead of downloading.

.PARAMETER DryRun
Print one [DRY] line per step and write nothing.

.PARAMETER Check
Report whether the installation is current; throws on drift. Cannot be combined with -Update or -Uninstall.

.PARAMETER Update
Install the requested or latest release over the current one. Cannot be combined with -Check or -Uninstall.

.PARAMETER Uninstall
Remove what the installer added. Cannot be combined with -Check or -Update.

.EXAMPLE
& ([scriptblock]::Create((Invoke-WebRequest -UseBasicParsing https://raw.githubusercontent.com/belajarcarabelajar/snipset-cli/main/install.ps1).Content)) -Version v0.2.0 -AddPath

Installs v0.2.0 into $env:LOCALAPPDATA\Snipset\bin and adds that directory to the user PATH.

.EXAMPLE
.\install.ps1 -Version v0.1.0 -WithMcp claude,codex -DryRun

Prints the steps for installing v0.1.0 and registering MCP for Claude Code and Codex, without writing anything.
#>
[CmdletBinding()]
param(
  [string]$Version,
  [string]$InstallDir,
  [switch]$AddPath,
  [string[]]$WithMcp,
  [string]$From,
  [switch]$DryRun,
  [switch]$Check,
  [switch]$Update,
  [switch]$Uninstall
)
# The one-liner runs inside the caller's session, whose strict mode would otherwise reach every part.
Set-StrictMode -Off
$ErrorActionPreference = 'Stop'
# Windows PowerShell 5.1 redraws a progress bar per downloaded chunk, which slows Invoke-WebRequest many times over.
$ProgressPreference = 'SilentlyContinue'
$repo = 'belajarcarabelajar/snipset-cli'
$baseUrl = if ($env:SNIPSET_RELEASE_BASE_URL) { $env:SNIPSET_RELEASE_BASE_URL } else { "https://github.com/$repo/releases/download" }

function Enable-SnipsetTls12 {
  param([string]$Edition = $PSVersionTable.PSEdition)
  # Windows PowerShell may offer only TLS 1.0 while GitHub requires TLS 1.2 since 2018-02-01; pwsh (Core) negotiates
  # it already. The setting is process-wide, so the previous value is returned for Restore-SnipsetTls.
  if ($Edition -eq 'Core') { return $null }
  $previous = [Net.ServicePointManager]::SecurityProtocol
  if ($previous -band [Net.SecurityProtocolType]::Tls12) { return $null }
  [Net.ServicePointManager]::SecurityProtocol = $previous -bor [Net.SecurityProtocolType]::Tls12
  $previous
}

function Restore-SnipsetTls {
  param($Previous)
  if ($null -ne $Previous) { [Net.ServicePointManager]::SecurityProtocol = $Previous }
}

function Write-SnipsetReport {
  param([string]$Status, [string]$Item, [string]$Detail)
  Write-Output "[$Status] ${Item}: $Detail"
  # $run is the hashtable of the Invoke-Snipset* function on the call stack, found by dynamic scoping;
  # unit tests that dot-source a part call this without one.
  if ($run -is [hashtable]) {
    $counter = @{ DRIFT = 'drift'; MISSING = 'drift'; KEEP = 'kept'; REMOVED = 'removed'; FAIL = 'fail' }[$Status]
    if ($counter) { $run[$counter] = [int]$run[$counter] + 1 }
  }
}

function Invoke-SnipsetAction {
  param([string]$Description, [scriptblock]$Action)
  if ($DryRun) {
    Write-Output "[DRY] $Description"
    return
  }
  & $Action
}

function Get-SnipsetMode {
  param([switch]$Check, [switch]$Update, [switch]$Uninstall)
  $picked = @(@{ check = $Check; update = $Update; uninstall = $Uninstall }.GetEnumerator() | Where-Object { $_.Value } | ForEach-Object { $_.Key })
  if ($picked.Count -gt 1) { throw 'install.ps1: use only one of -Check, -Update, -Uninstall' }
  if ($picked.Count -eq 1) { $picked[0] } else { 'install' }
}

function Resolve-SnipsetMcpIds {
  param([string[]]$WithMcp)
  $known = @('claude', 'codex', 'gemini', 'opencode', 'cursor', 'vscode')
  $ids = [Collections.Generic.List[string]]::new()
  $requested = if ($WithMcp) { @($WithMcp | ForEach-Object { "$_" -split ',' } | ForEach-Object { $_.Trim().ToLowerInvariant() } | Where-Object { $_ }) } else { @() }
  foreach ($id in $requested) {
    if ($id -eq 'all') { $expanded = $known }
    elseif ($known -contains $id) { $expanded = @($id) }
    else { throw "install.ps1: unknown MCP id $id (known: $($known -join ', '), all)" }
    foreach ($one in $expanded) { if (-not $ids.Contains($one)) { $ids.Add($one) } }
  }
  , $ids.ToArray()
}

function Resolve-SnipsetInstallDir {
  param([string]$InstallDir)
  if (-not $InstallDir) {
    if (-not $env:LOCALAPPDATA) { throw 'install.ps1: LOCALAPPDATA is not set; pass -InstallDir <dir>' }
    $InstallDir = Join-Path $env:LOCALAPPDATA 'Snipset\bin'
  }
  # PATH splits entries at ; and a " changes how the entry is quoted, so either would point PATH somewhere else.
  $refusal = "install.ps1: the install directory must not contain ; or `" (got $InstallDir)"
  if ($InstallDir -match '[;"]') { throw $refusal }
  # [IO.Path] alone resolves against the process directory, which Set-Location does not move.
  $here = (Get-Location -PSProvider FileSystem).ProviderPath
  $full = [IO.Path]::GetFullPath([IO.Path]::Combine($here, $InstallDir))
  if ($full -match '[;"]') { throw $refusal }
  $full
}
$target = 'x86_64-pc-windows-msvc'

function Test-SnipsetWindowsHost {
  # Windows PowerShell 5.1 has no $IsWindows and runs only on Windows; pwsh 7 defines it on every OS,
  # so OS=Windows_NT set by hand on Linux must not count.
  if ($null -ne $IsWindows) { return [bool]$IsWindows }
  $env:OS -eq 'Windows_NT'
}

function Get-SnipsetArchDecision {
  param([string]$Arch, [string]$Wow, [int]$Build)
  # A 32-bit process sees x86 in PROCESSOR_ARCHITECTURE and the real CPU in PROCESSOR_ARCHITEW6432.
  $effective = if ($Wow) { $Wow } else { $Arch }
  if ($effective -eq 'AMD64') { return 'ok' }
  if ($effective -eq 'ARM64') {
    # Windows 11 (build 22000) emulates x64 on Arm; Windows 10 on Arm emulates x86 only.
    if ($Build -ge 22000) { return 'ok-emulated' }
    return 'refuse:Windows 10 on Arm cannot run the x64 build; use Windows 11'
  }
  "refuse:unsupported CPU $(if ($effective) { $effective } else { 'unknown' })"
}

function Assert-SnipsetPlatform {
  param(
    [string]$Arch = $env:PROCESSOR_ARCHITECTURE,
    [string]$Wow = $env:PROCESSOR_ARCHITEW6432,
    [int]$Build = [Environment]::OSVersion.Version.Build
  )
  if (-not (Test-SnipsetWindowsHost)) {
    if ($env:SNIPSET_INSTALL_ALLOW_NON_WINDOWS -eq '1') {
      Write-SnipsetReport -Status SKIP -Item 'platform' -Detail 'non-Windows host (test switch)'
      return
    }
    throw 'install.ps1 installs the Windows build; on Linux use install.sh'
  }
  $cpu = if ($Wow) { $Wow } else { $Arch }
  $decision = Get-SnipsetArchDecision -Arch $Arch -Wow $Wow -Build $Build
  if ($decision -like 'refuse:*') { throw "install.ps1: $($decision.Substring('refuse:'.Length))" }
  if ($decision -eq 'ok-emulated') {
    Write-SnipsetReport -Status NOTE -Item 'platform' -Detail "Windows $cpu build $Build runs the x64 build under emulation"
  } else {
    Write-SnipsetReport -Status OK -Item 'platform' -Detail "Windows $cpu build $Build"
  }
}
function Get-SnipsetFromVersion {
  param([string]$From)
  $sums = Join-Path $From 'SHA256SUMS'
  if (-not (Test-Path -LiteralPath $sums -PathType Leaf)) { throw "install.ps1: $sums is missing" }
  $pattern = '^[0-9a-fA-F]{64}\s+\*?snipset-cli-(v\d+\.\d+\.\d+([.-][0-9A-Za-z.-]+)?)-' + [regex]::Escape($target) + '\.zip$'
  $found = @(Get-Content -LiteralPath $sums | ForEach-Object { if ($_ -match $pattern) { $Matches[1] } } | Sort-Object -Unique)
  if ($found.Count -ne 1) { throw "install.ps1: expected one snipset-cli-v<VERSION>-$target.zip in $sums, found $($found.Count); pass -Version" }
  $found[0]
}
function Resolve-SnipsetVersion {
  if ($Version -and $Version -notmatch '^v?\d+\.\d+\.\d+([.-][0-9A-Za-z.-]+)?$') { throw 'install.ps1: invalid version' }
  if ($Version -and $Version -notlike 'v*') { $Version = "v$Version" }
  if (-not $Version -and $From) { $Version = Get-SnipsetFromVersion -From $From }
  if (-not $Version) { $Version = (Invoke-RestMethod -Uri "https://api.github.com/repos/$repo/releases/latest").tag_name }
  if ($Version -notmatch '^v\d+\.\d+\.\d+([.-][0-9A-Za-z.-]+)?$') { throw 'install.ps1: release version was not found' }
  $Version
}
function Get-SnipsetRelease {
  param([string]$Temp)
  $sums = Join-Path $temp 'SHA256SUMS'
  $zip = Join-Path $temp $archive
  if ($From) {
    foreach ($name in 'SHA256SUMS', $archive) {
      $source = Join-Path $From $name
      if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { throw "install.ps1: $source is missing" }
      Copy-Item -LiteralPath $source -Destination (Join-Path $temp $name)
    }
  } else {
    # A loopback http URL is a local mirror or a test server, so nothing crosses the network unencrypted.
    $loopback = $baseUrl -match '^http://(127\.0\.0\.1|\[::1\]|localhost)(:\d+)?(/|$)'
    if ($baseUrl -notlike 'https://*' -and -not $loopback) { throw "install.ps1: SNIPSET_RELEASE_BASE_URL must start with https:// (got $baseUrl); use -From <dir> for local files" }
    Invoke-WebRequest -UseBasicParsing -Uri "$releaseUrl/SHA256SUMS" -OutFile $sums
    Invoke-WebRequest -UseBasicParsing -Uri "$releaseUrl/$archive" -OutFile $zip
  }
  # `*` is the binary-mode marker that `sha256sum -b` writes before the name.
  $entry = '^([0-9a-fA-F]{64})\s+\*?' + [regex]::Escape($archive) + '$'
  $line = Get-Content -LiteralPath $sums | Where-Object { $_ -match $entry } | Select-Object -First 1
  if (-not $line -or $line -notmatch $entry) { throw 'install.ps1: checksum entry missing' }
  $expected = $Matches[1].ToLowerInvariant()
  $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $zip).Hash.ToLowerInvariant()
  if ($actual -ne $expected) { throw 'install.ps1: checksum mismatch' }
  $zip
}
function Test-SnipsetArchive {
  param([string]$Zip)
  # Windows PowerShell 5.1 runs on .NET Framework, where ZipFile lives in this assembly.
  Add-Type -AssemblyName System.IO.Compression.FileSystem
  $zipArchive = [IO.Compression.ZipFile]::OpenRead($zip)
  try {
    foreach ($entry in $zipArchive.Entries) {
      if ([IO.Path]::IsPathRooted($entry.FullName) -or $entry.FullName -match '(^|[\\/])\.\.([\\/]|$)' -or $entry.FullName -match '(^|[\\/])\.git([\\/]|$)') { throw 'install.ps1: unsafe archive entry' }
    }
  } finally {
    $zipArchive.Dispose()
  }
}
function Test-SnipsetBinary {
  param([string]$Path)
  # Windows PowerShell 5.1 turns native stderr into a terminating error under 'Stop'; this scope only.
  $ErrorActionPreference = 'Continue'
  try { $out = @(& $Path --version 2>$null) } catch { return $false }
  ($LASTEXITCODE -eq 0) -and (($out -join "`n").StartsWith('snipset '))
}
function Get-SnipsetInstalledVersion {
  param([string]$InstallDir)
  if (-not (Test-SnipsetWindowsHost)) { return $null }
  $exe = Join-Path $InstallDir 'snipset.exe'
  if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) { return $null }
  $ErrorActionPreference = 'Continue'
  try { $out = @(& $exe --version 2>$null) } catch { return $null }
  if ($LASTEXITCODE -eq 0 -and ($out -join "`n") -match '^snipset v?(\d+\.\d+\.\d+([.-][0-9A-Za-z.-]+)?)') { return $Matches[1] }
  $null
}
function Move-SnipsetExe {
  param([string]$Candidate, [string]$Exe)
  # Windows refuses to overwrite a running exe but lets it be renamed, so a busy one is moved aside first.
  # Returns 'moved', 'in-use', or the path the old exe was moved to.
  try {
    Move-Item -LiteralPath $Candidate -Destination $Exe -Force
    return 'moved'
  } catch [IO.IOException], [UnauthorizedAccessException] { }
  $aside = "$Exe.old-$PID"
  try { Move-Item -LiteralPath $Exe -Destination $aside -Force } catch [IO.IOException], [UnauthorizedAccessException] { return 'in-use' }
  try {
    Move-Item -LiteralPath $Candidate -Destination $Exe -Force
  } catch [IO.IOException], [UnauthorizedAccessException] {
    Move-Item -LiteralPath $aside -Destination $Exe -Force
    return 'in-use'
  }
  $aside
}
function Install-SnipsetBinary {
  param([string]$Zip, [string]$Stage, [string]$InstallDir)
  [void][IO.Directory]::CreateDirectory($InstallDir)
  # Expand-Archive tests an existing destination as a wildcard, so with a [ in the path it must create the stage itself.
  Expand-Archive -LiteralPath $Zip -DestinationPath $Stage -Force
  $candidate = Join-Path $stage 'snipset.exe'
  if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { throw 'install.ps1: archive has no snipset.exe' }
  $windows = Test-SnipsetWindowsHost
  if ($windows) {
    if (-not (Test-SnipsetBinary -Path $candidate)) { throw 'install.ps1: the downloaded snipset.exe failed "snipset.exe --version"; the installed snipset.exe was not changed' }
  } else {
    Write-SnipsetReport -Status SKIP -Item 'smoke' -Detail 'not a Windows host'
  }
  $exe = Join-Path $InstallDir 'snipset.exe'
  # Uninstall later deletes what it finds here, so never put our exe over someone else's file or a link.
  # Off Windows the existing exe cannot be run, so only a link is refused there.
  $existing = Get-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue
  if ($existing -and ($existing.LinkType -or ($windows -and -not (Test-SnipsetBinary -Path $exe)))) {
    throw "install.ps1: $exe exists and is not a snipset install; move it aside or pass -InstallDir"
  }
  if ($windows) {
    $moved = Move-SnipsetExe -Candidate $candidate -Exe $exe
    if ($moved -eq 'in-use') {
      Write-SnipsetReport -Status FAIL -Item 'binary' -Detail 'in use (close the program using it)'
      return
    }
    if ($moved -ne 'moved') { Write-SnipsetReport -Status NOTE -Item 'binary' -Detail "$exe was in use; the old one is now $moved, delete it once that program exits" }
  } else {
    Move-Item -LiteralPath $candidate -Destination $exe -Force
  }
  if ($windows) {
    # Mark of the Web on the zip may or may not reach the extracted exe; Unblock-File is a no-op when absent.
    Unblock-File -LiteralPath $exe
  } else {
    Write-SnipsetReport -Status SKIP -Item 'unblock' -Detail 'not a Windows host'
  }
}
function Test-SnipsetPathEntrySame {
  param([string]$Entry, [string]$Dir)
  [string]::Equals($Entry.TrimEnd('\'), $Dir.TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase)
}

function Get-SnipsetPathEntries {
  param([string]$Raw)
  "$Raw" -split ';' | Where-Object { $_ -ne '' }
}

function Test-SnipsetPathEntry {
  param([string]$Raw, [string]$Dir)
  @(Get-SnipsetPathEntries -Raw $Raw | Where-Object { Test-SnipsetPathEntrySame -Entry $_ -Dir $Dir }).Count -gt 0
}

function Add-SnipsetPathEntry {
  param([string]$Raw, [string]$Dir)
  # @() keeps a value holding one entry an array; without it, appending joins two strings (C:\aC:\b).
  $parts = @(Get-SnipsetPathEntries -Raw $Raw)
  if (-not (Test-SnipsetPathEntry -Raw $Raw -Dir $Dir)) { $parts += $Dir }
  $parts -join ';'
}

function Remove-SnipsetPathEntry {
  param([string]$Raw, [string]$Dir)
  @(Get-SnipsetPathEntries -Raw $Raw | Where-Object { -not (Test-SnipsetPathEntrySame -Entry $_ -Dir $Dir) }) -join ';'
}

function Get-SnipsetUserPath {
  if (-not (Test-SnipsetWindowsHost)) {
    # Out-Host keeps the report line out of the value the caller assigns.
    Write-SnipsetReport -Status SKIP -Item 'path' -Detail 'not a Windows host' | Out-Host
    return $null
  }
  # The registry value, not [Environment]::GetEnvironmentVariable, so %USERPROFILE%-style entries stay unexpanded.
  (Get-Item 'HKCU:\Environment').GetValue('Path', '', 'DoNotExpandEnvironmentNames')
}

function Set-SnipsetUserPath {
  param([string]$Raw)
  if (-not (Test-SnipsetWindowsHost)) {
    Write-SnipsetReport -Status SKIP -Item 'path' -Detail 'not a Windows host'
    return
  }
  Set-ItemProperty -Path 'HKCU:\Environment' -Name Path -Value $Raw -Type ExpandString
  # Set-ItemProperty sends no WM_SETTINGCHANGE; SetEnvironmentVariable on a User variable does, so new shells see the PATH.
  $probe = 'SNIPSET_INSTALL_PATH_BROADCAST'
  [Environment]::SetEnvironmentVariable($probe, '1', 'User')
  [Environment]::SetEnvironmentVariable($probe, $null, 'User')
}

# Written only when the install itself adds the entry, so uninstall never drops an entry the user had before.
function Get-SnipsetPathMarker {
  param([string]$Dir)
  Join-Path $Dir '.snipset-path-added'
}

function Install-SnipsetPathEnv {
  param([string]$Dir)
  if (-not (Test-SnipsetWindowsHost)) {
    Write-SnipsetReport -Status SKIP -Item 'path' -Detail 'not a Windows host'
    return
  }
  $raw = Get-SnipsetUserPath
  if (Test-SnipsetPathEntry -Raw $raw -Dir $Dir) {
    Write-SnipsetReport -Status OK -Item 'path' -Detail "$Dir is already on the user PATH"
    return
  }
  Set-SnipsetUserPath -Raw (Add-SnipsetPathEntry -Raw $raw -Dir $Dir)
  [void][IO.Directory]::CreateDirectory($Dir)
  [IO.File]::WriteAllText((Get-SnipsetPathMarker -Dir $Dir), "$Dir`n")
  Write-SnipsetReport -Status ADD -Item 'path' -Detail "added $Dir to the user PATH; open a new terminal to use it"
}

function Test-SnipsetPathEnv {
  param([string]$Dir)
  if (-not (Test-SnipsetWindowsHost)) {
    Write-SnipsetReport -Status SKIP -Item 'path' -Detail 'not a Windows host'
    return
  }
  if (Test-SnipsetPathEntry -Raw (Get-SnipsetUserPath) -Dir $Dir) {
    Write-SnipsetReport -Status OK -Item 'path' -Detail "$Dir is on the user PATH"
  } else {
    Write-SnipsetReport -Status MISSING -Item 'path' -Detail "$Dir is not on the user PATH"
  }
}

function Remove-SnipsetPathEnv {
  param([string]$Dir, [switch]$ExeKept)
  if (-not (Test-SnipsetWindowsHost)) {
    Write-SnipsetReport -Status SKIP -Item 'path' -Detail 'not a Windows host'
    return
  }
  $marker = Get-SnipsetPathMarker -Dir $Dir
  $recorded = [IO.File]::Exists($marker)
  $raw = Get-SnipsetUserPath
  if (-not (Test-SnipsetPathEntry -Raw $raw -Dir $Dir)) {
    if ($recorded -and -not $ExeKept) { [IO.File]::Delete($marker) }
    Write-SnipsetReport -Status SKIP -Item 'path' -Detail "$Dir is not on the user PATH"
    return
  }
  if (-not $recorded) {
    Write-SnipsetReport -Status KEEP -Item 'path' -Detail "$Dir was on the user PATH before the install"
    return
  }
  if ($ExeKept) {
    Write-SnipsetReport -Status KEEP -Item 'path' -Detail "$Dir stays on the user PATH while snipset.exe is kept"
    return
  }
  Set-SnipsetUserPath -Raw (Remove-SnipsetPathEntry -Raw $raw -Dir $Dir)
  [IO.File]::Delete($marker)
  Write-SnipsetReport -Status REMOVED -Item 'path' -Detail "$Dir from the user PATH"
}
function Get-SnipsetMcpCliName {
  param([string]$Id)
  @{ claude = 'claude'; codex = 'codex'; gemini = 'gemini'; vscode = 'code' }[$Id]
}

function Find-SnipsetMcpCli {
  param([string]$Id)
  $name = Get-SnipsetMcpCliName -Id $Id
  if (-not $name) { return $null }
  # Applications only: npm also installs a .ps1 shim, which would run in-process under the caller's execution policy.
  $found = Get-Command -Name $name -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($found) { $found.Source }
}

function Get-SnipsetMcpFile {
  param([string]$Id)
  $onWindows = [Environment]::OSVersion.Platform -eq [PlatformID]::Win32NT
  switch ($Id) {
    'opencode' { [IO.Path]::Combine($HOME, '.config', 'opencode', 'opencode.json') }
    'cursor' { [IO.Path]::Combine($HOME, '.cursor', 'mcp.json') }
    'vscode' {
      if ($onWindows) { [IO.Path]::Combine($env:APPDATA, 'Code', 'User', 'mcp.json') }
      else { [IO.Path]::Combine($HOME, '.config', 'Code', 'User', 'mcp.json') }
    }
  }
}

function Get-SnipsetMcpServerArgs {
  param([string]$Db)
  if ($Db) { @('mcp', '--db', $Db) } else { @('mcp') }
}

function Get-SnipsetMcpCursorEntry {
  param([string]$Bin, [string]$Db)
  [ordered]@{ type = 'stdio'; command = $Bin; args = @(Get-SnipsetMcpServerArgs -Db $Db) }
}

function Get-SnipsetMcpFileContent {
  param([string]$Id, [string]$Bin, [string]$Db)
  if ($Id -eq 'opencode') {
    $command = @($Bin) + @(Get-SnipsetMcpServerArgs -Db $Db)
    $doc = [ordered]@{ '$schema' = 'https://opencode.ai/config.json'; mcp = [ordered]@{ snipset = [ordered]@{ type = 'local'; command = $command; enabled = $true } } }
  } else {
    $doc = [ordered]@{ mcpServers = [ordered]@{ snipset = (Get-SnipsetMcpCursorEntry -Bin $Bin -Db $Db) } }
  }
  (ConvertTo-Json -InputObject $doc -Depth 5 -Compress) + "`n"
}

function Invoke-SnipsetMcpCli {
  param([string]$Path, [string[]]$Arguments)
  # Windows PowerShell 5.1 turns redirected native stderr into a terminating error under 'Stop'.
  $ErrorActionPreference = 'Continue'
  $PSNativeCommandUseErrorActionPreference = $false
  # Legacy passing (Windows PowerShell 5.1, pwsh before 7.3, and pwsh 7.3+ for .cmd shims such as code.cmd)
  # drops inner double quotes unless they are escaped the way the C runtime parses them.
  $passing = Get-Variable -Name PSNativeCommandArgumentPassing -ValueOnly -ErrorAction SilentlyContinue
  if ((-not $passing) -or ("$passing" -eq 'Legacy') -or ("$passing" -eq 'Windows' -and $Path -match '\.(bat|cmd)$')) {
    $Arguments = @($Arguments | ForEach-Object { $_ -replace '(\\*)"', '$1$1\"' })
  }
  $output = @(& $Path @Arguments 2>&1)
  $code = $LASTEXITCODE
  $stdout = @($output | Where-Object { $_ -isnot [Management.Automation.ErrorRecord] } | ForEach-Object { "$_" })
  $stderr = @($output | Where-Object { $_ -is [Management.Automation.ErrorRecord] } | ForEach-Object { "$_" })
  $err = if ($stderr.Count -and $stderr[0].Trim()) { $stderr[0].Trim() } else { "exit status $code" }
  [pscustomobject]@{ Code = $code; Out = $stdout; Err = $err }
}

function Get-SnipsetMcpGeminiSettings {
  [IO.Path]::Combine($HOME, '.gemini', 'settings.json')
}

# Only a user-scope entry is the installer's: "remove --scope user" never touches
# another scope, and an entry in another scope can shadow the user one.
function Get-SnipsetMcpClaudeState {
  param([string]$Cli, [string]$Bin)
  $result = Invoke-SnipsetMcpCli -Path $Cli -Arguments @('mcp', 'get', 'snipset')
  if ($result.Code -ne 0) { return 'absent' }
  $scope = ''
  $first = ''
  $mine = $false
  $binSeen = $false
  foreach ($line in $result.Out) {
    if ($line -match '^\s*scope:\s*(.*?)\s*$') {
      $scope = switch -Regex ($Matches[1]) {
        '^user' { 'user' }
        '^local' { 'local' }
        '^project' { 'project' }
        default { ($_ -split '\s+')[0] }
      }
      if (-not $first) { $first = $scope }
    } elseif ($line -match '^\s*command:\s*(.*?)\s*$') {
      if ($Matches[1] -ceq $Bin) {
        $binSeen = $true
        if ($scope -eq 'user') { $mine = $true }
      }
      $scope = ''
    }
  }
  if (-not $first) { $first = 'unknown' }
  if ($mine) { return 'mine user' }
  if ($binSeen) { return "scoped $first" }
  "foreign $first"
}

# The user settings file decides ownership; "gemini mcp list" merges every scope.
function Get-SnipsetMcpGeminiState {
  param([string]$Cli, [string]$Bin)
  $settings = Get-SnipsetMcpGeminiSettings
  $text = if ([IO.File]::Exists($settings)) { [IO.File]::ReadAllText($settings) } else { '' }
  if ($text.Contains('snipset')) {
    # Parsed, not searched: a "snipset-dev" entry holding the bin must not make "snipset" look ours,
    # and Windows PowerShell 5.1 writes ' as \u0027.
    try { $doc = ConvertFrom-Json -InputObject $text } catch { return 'unreadable' }
    $servers = if ($doc) { $doc.mcpServers }
    $entry = if ($servers) { @($servers.PSObject.Properties | Where-Object { $_.Name -ceq 'snipset' })[0] }
    if ($entry) {
      if ("$($entry.Value.command)" -ceq $Bin) { return 'mine' }
      return 'foreign'
    }
  }
  $result = Invoke-SnipsetMcpCli -Path $Cli -Arguments @('mcp', 'list')
  if ($result.Code -eq 0 -and ($result.Out | Where-Object { $_ -match '(^|\s)snipset:' })) { return 'scoped' }
  'absent'
}

function Get-SnipsetMcpUnreadableDetail {
  "$(Get-SnipsetMcpGeminiSettings) is not valid JSON; left untouched"
}

# Detail for an entry the installer leaves alone because it sits in another scope.
function Get-SnipsetMcpScopedDetail {
  param([string]$Id, [string]$Scope)
  if ($Id -eq 'claude') { return "$Scope entry left untouched" }
  "snipset is registered outside $(Get-SnipsetMcpGeminiSettings); left untouched"
}

# Returns nocli, absent, other (file without snipset), mine, foreign, scoped (the bin
# is registered in a scope the installer does not own), or unreadable (gemini settings that are
# not JSON); claude adds a second word naming the scope.
function Get-SnipsetMcpState {
  param([string]$Id, [string]$Bin)
  $cli = Find-SnipsetMcpCli -Id $Id
  if ($Id -in 'claude', 'codex', 'gemini') {
    if (-not $cli) { return 'nocli' }
    if ($Id -eq 'claude') { return Get-SnipsetMcpClaudeState -Cli $cli -Bin $Bin }
    if ($Id -eq 'gemini') { return Get-SnipsetMcpGeminiState -Cli $cli -Bin $Bin }
    $result = Invoke-SnipsetMcpCli -Path $cli -Arguments @('mcp', 'get', 'snipset')
    if ($result.Code -ne 0) { return 'absent' }
    $command = ''
    foreach ($line in $result.Out) {
      if ($line -match '^\s*command:\s*(.*?)\s*$') { $command = $Matches[1]; break }
    }
    if ($command -ceq $Bin) { return 'mine' }
    return 'foreign'
  }
  $file = Get-SnipsetMcpFile -Id $Id
  if (-not [IO.File]::Exists($file)) { return 'absent' }
  $text = [IO.File]::ReadAllText($file)
  # The files hold the path JSON-encoded, so Windows backslashes appear doubled.
  if ($text.Contains((ConvertTo-Json -InputObject $Bin -Compress))) { return 'mine' }
  if ($text.Contains('"snipset"')) { return 'foreign' }
  'other'
}

function Install-SnipsetMcp {
  param([string[]]$Ids, [string]$Bin, [string]$Db)
  foreach ($id in $Ids) {
    try {
      $cliName = Get-SnipsetMcpCliName -Id $id
      if ($cliName -and -not (Find-SnipsetMcpCli -Id $id)) {
        Write-SnipsetReport -Status SKIP -Item $id -Detail "$cliName not on PATH"
        continue
      }
      $state = ("$(Get-SnipsetMcpState -Id $id -Bin $Bin)" -split ' ')[0]
      $file = Get-SnipsetMcpFile -Id $id
      if ($id -in 'opencode', 'cursor') {
        if ($state -eq 'absent') {
          [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file))
          [IO.File]::WriteAllText($file, (Get-SnipsetMcpFileContent -Id $id -Bin $Bin -Db $Db), (New-Object Text.UTF8Encoding $false))
          Write-SnipsetReport -Status ADD -Item $id -Detail "wrote $file"
          continue
        }
        if ($id -eq 'opencode') {
          Write-Host "MCP config exists; leaving $file untouched"
        } else {
          $entry = ConvertTo-Json -InputObject (Get-SnipsetMcpCursorEntry -Bin $Bin -Db $Db) -Depth 5 -Compress
          Write-Host "Cursor config exists; add this to mcpServers in ${file}: `"snipset`":$entry"
        }
        if ($state -eq 'other') {
          Write-SnipsetReport -Status KEEP -Item $id -Detail "$file exists; left untouched"
        } else {
          Write-SnipsetReport -Status KEEP -Item $id -Detail 'snipset is already registered'
        }
        continue
      }
      if ($state -eq 'unreadable') {
        Write-SnipsetReport -Status KEEP -Item $id -Detail (Get-SnipsetMcpUnreadableDetail)
        continue
      }
      if ($state -in 'mine', 'foreign', 'scoped') {
        Write-SnipsetReport -Status KEEP -Item $id -Detail 'snipset is already registered'
        continue
      }
      $server = @($Bin) + @(Get-SnipsetMcpServerArgs -Db $Db)
      $argv = switch ($id) {
        'claude' { @('mcp', 'add', '--scope', 'user', 'snipset', '--') + $server }
        'codex' { @('mcp', 'add', 'snipset', '--') + $server }
        'gemini' { @('mcp', 'add', '--scope', 'user', 'snipset') + $server }
        'vscode' {
          $json = ConvertTo-Json -InputObject ([ordered]@{ name = 'snipset'; command = $Bin; args = @(Get-SnipsetMcpServerArgs -Db $Db) }) -Depth 5 -Compress
          @('--add-mcp', $json)
        }
      }
      $result = Invoke-SnipsetMcpCli -Path (Find-SnipsetMcpCli -Id $id) -Arguments $argv
      if ($result.Code -eq 0) {
        Write-SnipsetReport -Status ADD -Item $id -Detail 'snipset registered'
      } else {
        Write-SnipsetReport -Status FAIL -Item $id -Detail $result.Err
      }
    } catch {
      Write-SnipsetReport -Status FAIL -Item $id -Detail $_.Exception.Message
    }
  }
}

function Test-SnipsetMcp {
  param([string[]]$Ids, [string]$Bin)
  if (-not $Ids) {
    Write-SnipsetReport -Status SKIP -Item 'mcp' -Detail 'no -WithMcp list'
    return
  }
  foreach ($id in $Ids) {
    try {
      $cliName = Get-SnipsetMcpCliName -Id $id
      if ($cliName -and -not (Find-SnipsetMcpCli -Id $id)) {
        Write-SnipsetReport -Status SKIP -Item $id -Detail "$cliName not on PATH"
        continue
      }
      $state, $scope = "$(Get-SnipsetMcpState -Id $id -Bin $Bin)" -split ' ', 2
      switch ($state) {
        'mine' { Write-SnipsetReport -Status OK -Item $id -Detail "snipset points at $Bin" }
        'foreign' { Write-SnipsetReport -Status KEEP -Item $id -Detail 'snipset points elsewhere' }
        'scoped' { Write-SnipsetReport -Status KEEP -Item $id -Detail (Get-SnipsetMcpScopedDetail -Id $id -Scope $scope) }
        'unreadable' { Write-SnipsetReport -Status KEEP -Item $id -Detail (Get-SnipsetMcpUnreadableDetail) }
        { $_ -eq 'other' -and $id -in 'opencode', 'cursor' } { Write-SnipsetReport -Status KEEP -Item $id -Detail "$(Get-SnipsetMcpFile -Id $id) exists without snipset; not managed by the installer" }
        default { Write-SnipsetReport -Status MISSING -Item $id -Detail 'snipset is not registered' }
      }
    } catch {
      Write-SnipsetReport -Status FAIL -Item $id -Detail $_.Exception.Message
    }
  }
}

function Remove-SnipsetMcp {
  param([string[]]$Ids, [string]$Bin, [string]$Db)
  if (-not $Ids) { $Ids = @('claude', 'codex', 'gemini', 'opencode', 'cursor', 'vscode') }
  foreach ($id in $Ids) {
    try {
      $state, $scope = "$(Get-SnipsetMcpState -Id $id -Bin $Bin)" -split ' ', 2
      $file = Get-SnipsetMcpFile -Id $id
      if ($state -eq 'nocli') {
        Write-SnipsetReport -Status SKIP -Item $id -Detail "$(Get-SnipsetMcpCliName -Id $id) not on PATH"
      } elseif ($state -eq 'scoped' -or ($id -eq 'claude' -and $state -eq 'foreign')) {
        Write-SnipsetReport -Status KEEP -Item $id -Detail (Get-SnipsetMcpScopedDetail -Id $id -Scope $scope)
      } elseif ($state -eq 'foreign') {
        Write-SnipsetReport -Status KEEP -Item $id -Detail 'snipset points elsewhere'
      } elseif ($state -eq 'unreadable') {
        Write-SnipsetReport -Status KEEP -Item $id -Detail (Get-SnipsetMcpUnreadableDetail)
      } elseif ($state -ne 'mine') {
        Write-SnipsetReport -Status SKIP -Item $id -Detail 'snipset is not registered'
      } elseif ($id -eq 'vscode') {
        Write-SnipsetReport -Status KEEP -Item $id -Detail "remove snipset from $file by hand"
      } elseif ($file) {
        $expected = (New-Object Text.UTF8Encoding $false).GetBytes((Get-SnipsetMcpFileContent -Id $id -Bin $Bin -Db $Db))
        if ([Convert]::ToBase64String([IO.File]::ReadAllBytes($file)) -ceq [Convert]::ToBase64String($expected)) {
          [IO.File]::Delete($file)
          Write-SnipsetReport -Status REMOVED -Item $id -Detail $file
        } else {
          Write-SnipsetReport -Status KEEP -Item $id -Detail "$file differs from what the installer writes; remove snipset by hand"
        }
      } else {
        $argv = @{ claude = @('mcp', 'remove', '--scope', 'user', 'snipset'); codex = @('mcp', 'remove', 'snipset'); gemini = @('mcp', 'remove', '--scope', 'user', 'snipset') }[$id]
        $result = Invoke-SnipsetMcpCli -Path (Find-SnipsetMcpCli -Id $id) -Arguments $argv
        if ($result.Code -eq 0) {
          Write-SnipsetReport -Status REMOVED -Item $id -Detail 'snipset'
        } else {
          Write-SnipsetReport -Status FAIL -Item $id -Detail $result.Err
        }
      }
    } catch {
      Write-SnipsetReport -Status FAIL -Item $id -Detail $_.Exception.Message
    }
  }
}
# The called functions read these locals and the parameters through dynamic scoping, never a script-scope prefix:
# the README one-liner runs install.ps1 as a scriptblock, where the script scope is the caller's session.

function Test-SnipsetExe {
  param([string]$InstallDir)
  $exe = Join-Path $InstallDir 'snipset.exe'
  if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) {
    Write-SnipsetReport -Status MISSING -Item 'binary' -Detail "$exe not found"
    return
  }
  if (-not (Test-SnipsetWindowsHost)) {
    Write-SnipsetReport -Status OK -Item 'binary' -Detail "$exe (version not checked off Windows)"
    return
  }
  $have = Get-SnipsetInstalledVersion -InstallDir $InstallDir
  $want = $Version -replace '^v', ''
  if (-not $have) {
    Write-SnipsetReport -Status DRIFT -Item 'binary' -Detail "$exe does not answer --version as snipset"
  } elseif ($want -and $have -ne $want) {
    Write-SnipsetReport -Status DRIFT -Item 'binary' -Detail "snipset $have at $exe, expected $want"
  } else {
    Write-SnipsetReport -Status OK -Item 'binary' -Detail "snipset $have at $exe"
  }
}

function Remove-SnipsetExe {
  param([string]$InstallDir)
  $exe = Join-Path $InstallDir 'snipset.exe'
  $item = Get-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue
  if (-not $item) {
    Write-SnipsetReport -Status SKIP -Item 'binary' -Detail "$exe not found"
    return
  }
  # A link answers --version for its target, which the installer never wrote.
  if ($item.PSIsContainer -or $item.LinkType) {
    Write-SnipsetReport -Status KEEP -Item 'binary' -Detail "$exe is not a regular file; left in place"
    return
  }
  if ((Test-SnipsetWindowsHost) -and -not (Test-SnipsetBinary -Path $exe)) {
    Write-SnipsetReport -Status KEEP -Item 'binary' -Detail "$exe does not answer --version as snipset; left in place"
    return
  }
  try {
    Remove-Item -LiteralPath $exe -Force
  } catch {
    $e = $_.Exception
    # Windows refuses to delete a running exe, for example one an MCP host started.
    $detail = if ($e -is [IO.IOException] -or $e -is [UnauthorizedAccessException]) { "in use (close the program using it): $exe" } else { $e.Message }
    Write-SnipsetReport -Status FAIL -Item 'binary' -Detail $detail
    return
  }
  Write-SnipsetReport -Status REMOVED -Item 'binary' -Detail $exe
}

function Remove-SnipsetInstallDir {
  param([string]$InstallDir)
  $item = Get-Item -LiteralPath $InstallDir -Force -ErrorAction SilentlyContinue
  if (-not $item -or -not $item.PSIsContainer -or $item.LinkType) { return }
  if ([IO.Directory]::GetFileSystemEntries($InstallDir).Length -gt 0) { return }
  # Best effort like rmdir in install.sh: a dir in use stays, and that is not a failed uninstall.
  try { [IO.Directory]::Delete($InstallDir) } catch { }
}

function Invoke-SnipsetInstall {
  param([string[]]$McpIds = @())
  $run = @{ drift = 0; kept = 0; removed = 0; fail = 0; zip = $null }
  $Version = Resolve-SnipsetVersion
  $archive = "snipset-cli-$Version-$target.zip"
  $releaseUrl = "$baseUrl/$Version"
  $exe = Join-Path $InstallDir 'snipset.exe'
  $temp = Join-Path ([IO.Path]::GetTempPath()) ('snipset-install-' + [Guid]::NewGuid().ToString('N'))
  $stage = Join-Path $InstallDir ('.snipset-stage-' + [Guid]::NewGuid().ToString('N'))
  $fetch = if ($From) { "copy SHA256SUMS and $archive from $From" } else { "download SHA256SUMS and $archive from $releaseUrl" }
  try {
    Invoke-SnipsetAction -Description "$fetch and verify the checksum" -Action {
      New-Item -ItemType Directory -Force -Path $temp | Out-Null
      $run.zip = Get-SnipsetRelease -Temp $temp
    }
    Invoke-SnipsetAction -Description "check the entries of $archive" -Action { Test-SnipsetArchive -Zip $run.zip }
    Invoke-SnipsetAction -Description "install snipset.exe to $exe" -Action { Install-SnipsetBinary -Zip $run.zip -Stage $stage -InstallDir $InstallDir }
    if ($AddPath) { Invoke-SnipsetAction -Description "add $InstallDir to the user PATH" -Action { Install-SnipsetPathEnv -Dir $InstallDir } }
    foreach ($id in $McpIds) { Invoke-SnipsetAction -Description "register the snipset MCP server for $id" -Action { Install-SnipsetMcp -Ids @($id) -Bin $exe } }
    if ($run.fail -gt 0) { throw "install: $($run.fail) steps failed" }
    if ($DryRun) { Write-Output 'dry run: nothing was written' } else { Write-Output "Installed snipset $Version to $exe" }
  } finally {
    if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue }
  }
}

function Invoke-SnipsetCheck {
  param([string[]]$McpIds = @())
  $run = @{ drift = 0; kept = 0; removed = 0; fail = 0 }
  Test-SnipsetExe -InstallDir $InstallDir
  if ($AddPath) { Test-SnipsetPathEnv -Dir $InstallDir }
  if ($McpIds.Count) {
    Test-SnipsetMcp -Ids $McpIds -Bin (Join-Path $InstallDir 'snipset.exe')
  } else {
    Write-SnipsetReport -Status SKIP -Item 'mcp' -Detail 'no -WithMcp list'
  }
  # A check that could not run is not evidence of a current install.
  $n = $run.drift + $run.fail
  if ($n -gt 0) { throw "check: DRIFT ($n items)" }
  Write-Output 'check: CURRENT'
}

function Invoke-SnipsetUpdate {
  param([string[]]$McpIds = @())
  if ($DryRun) {
    Invoke-SnipsetInstall -McpIds $McpIds
    return
  }
  # Invoke-SnipsetInstall resolves again, sees this local, and so asks GitHub at most once.
  $Version = Resolve-SnipsetVersion
  $have = Get-SnipsetInstalledVersion -InstallDir $InstallDir
  if ($have -and $have -eq ($Version -replace '^v', '')) {
    Write-SnipsetReport -Status OK -Item 'update' -Detail "snipset $have is current"
    return
  }
  Invoke-SnipsetInstall -McpIds $McpIds
}

function Invoke-SnipsetUninstall {
  param([string[]]$McpIds = @())
  # The remove functions delete for real, so there is nothing safe to preview.
  if ($DryRun) { throw 'install.ps1: -DryRun cannot preview -Uninstall; run -Check to see what is installed' }
  $run = @{ drift = 0; kept = 0; removed = 0; fail = 0 }
  $exe = Join-Path $InstallDir 'snipset.exe'
  if ($McpIds.Count) {
    Remove-SnipsetMcp -Ids $McpIds -Bin $exe
  } else {
    Write-SnipsetReport -Status SKIP -Item 'mcp' -Detail 'no -WithMcp list'
  }
  Remove-SnipsetExe -InstallDir $InstallDir
  # The exe goes first: the PATH entry stays while a kept or locked exe still sits in the dir.
  $exeKept = [bool](Get-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue)
  Remove-SnipsetPathEnv -Dir $InstallDir -ExeKept:$exeKept
  Remove-SnipsetInstallDir -InstallDir $InstallDir
  Write-Output "uninstall: removed $($run.removed), kept $($run.kept)"
  if ($run.fail -gt 0) { throw "uninstall: $($run.fail) steps failed" }
}
$mode = Get-SnipsetMode -Check:$Check -Update:$Update -Uninstall:$Uninstall
$mcpIds = Resolve-SnipsetMcpIds -WithMcp $WithMcp
$InstallDir = Resolve-SnipsetInstallDir -InstallDir $InstallDir
Assert-SnipsetPlatform
$previousTls = Enable-SnipsetTls12
try {
  switch ($mode) {
    'check' { Invoke-SnipsetCheck -McpIds $mcpIds }
    'update' { Invoke-SnipsetUpdate -McpIds $mcpIds }
    'uninstall' { Invoke-SnipsetUninstall -McpIds $mcpIds }
    default { Invoke-SnipsetInstall -McpIds $mcpIds }
  }
} finally {
  Restore-SnipsetTls -Previous $previousTls
}
